import ast, builtins, glob, os, symtable, sys, collections

PKG = '/app/tally/reports'
ALLOWED_TOP = {'__init__.py', 'errors.py', 'tables.py', 'state.py', 'system.py', 'formatting', 'formatting.py', 'model', 'model.py',
               'loading', 'loading.py', 'aggregate', 'aggregate.py', 'renderers', 'cli', 'cli.py', '__pycache__'}
LAYER = {'errors': 0, 'tables': 0, 'state': 0, 'system': 0, 'formatting': 1, 'model': 1, 'loading': 2, 'aggregate': 3, 'renderers': 4, 'cli': 5, '__init__': 6}
problems = []
for e in os.listdir(PKG):
    if e not in ALLOWED_TOP:
        problems.append(f'unexpected entry {e}')
for n in ('errors', 'tables', 'state', 'system'):
    if not os.path.isfile(f'{PKG}/{n}.py'):
        problems.append(f'{n} must be a single module')
files = {}
for path in glob.glob(PKG + '/**/*.py', recursive=True):
    rel = os.path.relpath(path, PKG)[:-3]
    parts = rel.split('/')
    mod = 'tally.reports' if parts == ['__init__'] else 'tally.reports.' + '.'.join(p for p in parts if p != '__init__')
    files[mod] = path
    n = len(open(path).read().split('\n')) - (1 if open(path).read().endswith('\n') else 0)
    if n > 400:
        problems.append(f'{path}: {n} lines')
    if os.path.basename(path) == '__main__.py':
        problems.append('__main__.py present')


def layer(mod):
    parts = mod.split('.')
    if len(parts) == 2:
        return 6
    return LAYER[parts[2]]


def is_pkg(mod):
    return files[mod].endswith('__init__.py')


graph = collections.defaultdict(set)
for mod, path in files.items():
    tree = ast.parse(open(path).read())
    pkg = mod if is_pkg(mod) else mod.rsplit('.', 1)[0]
    for node in ast.walk(tree):
        targets = []
        if isinstance(node, ast.Import):
            for a in node.names:
                targets.append(a.name)
        elif isinstance(node, ast.ImportFrom):
            if node.level:
                base = pkg.split('.')
                base = base[:len(base) - (node.level - 1)]
                basemod = '.'.join(base + ([node.module] if node.module else []))
            else:
                basemod = node.module
            for a in node.names:
                full = basemod + '.' + a.name
                targets.append(full if full in files else basemod)
        elif isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == '__import__':
            problems.append(f'{mod}: __import__')
        for t in targets:
            if t.split('.')[0] == 'importlib':
                problems.append(f'{mod}: importlib')
            if t == 'tally' or (t.startswith('tally.') and not t.startswith('tally.reports')):
                problems.append(f'{mod}: imports {t}')
            if t.startswith('tally.reports'):
                if t not in files:
                    problems.append(f'{mod}: imports unknown {t}')
                    continue
                if t != mod:
                    graph[mod].add(t)
                if layer(t) > layer(mod):
                    problems.append(f'{mod} (L{layer(mod)}) imports {t} (L{layer(t)})')
# cycles
color = {}
def dfs(u, stack):
    color[u] = 1
    for v in graph[u]:
        if color.get(v) == 1:
            problems.append('cycle: ' + ' -> '.join(stack + [u, v]))
        elif v not in color:
            dfs(v, stack + [u])
    color[u] = 2
for m in files:
    if m not in color:
        dfs(m, [])

# __init__ content
t = ast.parse(open(PKG + '/__init__.py').read())
for i, node in enumerate(t.body):
    ok = isinstance(node, (ast.Import, ast.ImportFrom)) or (i == 0 and isinstance(node, ast.Expr) and isinstance(node.value, ast.Constant)) \
        or (isinstance(node, ast.Assign) and [x.id for x in node.targets] == ['__all__'])
    if not ok:
        problems.append(f'__init__ has {type(node).__name__} at {node.lineno}')

# definitions unique; undefined names; unused imports
defs = collections.defaultdict(list)
rebinders = collections.defaultdict(set)
toplevel_assign = collections.defaultdict(list)
for mod, path in files.items():
    src = open(path).read()
    tree = ast.parse(src)
    modnames = set(dir(builtins)) | {'__name__', '__file__', '__doc__'}
    imported = {}
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.ClassDef)):
            defs[node.name].append(mod)
            modnames.add(node.name)
        elif isinstance(node, (ast.Assign, ast.AnnAssign)):
            tg = node.targets if isinstance(node, ast.Assign) else [node.target]
            for x in tg:
                if isinstance(x, ast.Name):
                    modnames.add(x.id)
                    toplevel_assign[x.id].append(mod)
        elif isinstance(node, (ast.Import, ast.ImportFrom)):
            for a in node.names:
                nm = (a.asname or a.name).split('.')[0]
                modnames.add(nm)
                imported[nm] = node.lineno
    for node in ast.walk(tree):
        if isinstance(node, ast.Global):
            for n in node.names:
                rebinders[n].add(mod)
    table = symtable.symtable(src, path, 'exec')
    used_globals = set()
    def walk(tb):
        for s in tb.get_symbols():
            if (s.is_global() or (tb.get_type() == 'module' and s.is_referenced())) and s.is_referenced():
                used_globals.add(s.get_name())
                if s.get_name() not in modnames and tb.get_type() != 'module':
                    problems.append(f'{mod}: undefined name {s.get_name()} in {tb.get_name()}')
            if tb.get_type() == 'module' and s.is_referenced() and s.get_name() not in modnames:
                problems.append(f'{mod}: undefined module-level name {s.get_name()}')
        for c in tb.get_children():
            walk(c)
    walk(table)
    # names used anywhere (including annotations as strings under __future__)
    text_names = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name)} | {n.value.id for n in ast.walk(tree) if isinstance(n, ast.Attribute) and isinstance(n.value, ast.Name)}
    allnames = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Name):
            allnames.add(node.id)
    if not path.endswith('__init__.py'):
        for nm, ln in imported.items():
            if nm not in allnames and nm != 'annotations':
                problems.append(f'{mod}: unused import {nm}')
for n, mods in defs.items():
    if len(mods) > 1:
        problems.append(f'{n} defined in {mods}')
for n, mods in rebinders.items():
    homes = set(toplevel_assign[n])
    if len(homes) != 1 or mods != homes:
        problems.append(f'global {n}: rebound in {mods}, assigned at top in {homes}')
# from-imports of rebound names
for mod, path in files.items():
    tree = ast.parse(open(path).read())
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom):
            for a in node.names:
                if a.name in rebinders:
                    problems.append(f'{mod}: from-import of rebound {a.name}')
print('\n'.join(problems) or 'ALL CHECKS PASSED')
print(len(files), 'modules; rebound globals:', sorted(rebinders))

